    insightAr: "{وَسَيَصْلَوْنَ}؛ معناها: يدخلون النار ويقاسون حرها الملتهب ويحترقون بها حساً ومعنى.",
    insightEn: "the Qur’anic expression: they will enter the Fire and experience its burning heat in punishment.",
