    insightAr: "{فِي كَبَدٍ}؛ معناها: في مشقة، وتعب، وعناء مكابدة مستمرة ومواجهة لمتاعب وصدمات البيئة الحياتية فسيولوجياً ونفسياً منذ الولادة.",
